package com.tihai.utils;
import org.junit.jupiter.api.Test;import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.util.zip.*;import static org.junit.jupiter.api.Assertions.*;
class ReviewFeatureTest {
 static String page(String answers){return "<div class='singleQuesId' data='1'><div class='Zy_TItle'>1. 【单选题】选择正确的选项</div><ul><li>A. 甲</li><li>B. 乙</li></ul>"+answers+"</div>";}
 static Map<String,Object> official()throws Exception{return ReviewParser.read(page("<div class='rightAnswer'>正确答案：<span class='answerCon'>A</span></div><div class='myAnswer'>我的答案：<span class='answerCon'>B</span></div>")).get(0);}
 @Test void publishedAnswerAndStudentAnswerStaySeparate()throws Exception{Map<String,Object> q=official();assertEquals("A",q.get("platformAnswer"));assertEquals("B",q.get("studentAnswer"));assertEquals(true,q.get("gradeable"));assertEquals("A",q.get("canonicalAnswer"));}
 @Test void studentAnswerAndCorrectScoreNeverBecomePublishedAnswer()throws Exception{Map<String,Object> q=ReviewParser.read(page("<div class='myAnswer'>我的答案：<span class='answerCon'>A</span></div><span class='marking_dui'>正确</span><span>1分</span>")).get(0);assertEquals("",q.get("platformAnswer"));assertEquals(false,q.get("gradeable"));}
 @Test void hiddenAnswersAreNeverUsedForGrading()throws Exception{for(String attr:Arrays.asList("hidden","style='display:none'","class='hidden'")){Map<String,Object> q=ReviewParser.read(page("<div "+attr+"><div class='rightAnswer'>正确答案：<span class='answerCon'>A</span></div></div>")).get(0);assertEquals(false,q.get("gradeable"));assertEquals("",q.get("platformAnswer"));}}
 @Test void unpublishedAndAmbiguousAnswersAreNotGradeable()throws Exception{assertEquals(false,ReviewParser.read(page("")).get(0).get("gradeable"));assertEquals(false,ReviewParser.read(page("<div class='rightAnswer'>正确答案：A或B，无法确定</div>")).get(0).get("gradeable"));}
 @Test void multiSelectOrderAndJudgementSynonymsAreNormalized()throws Exception{assertEquals("AB",ReviewParser.canonical("multiple","B、A",Arrays.asList("A. 甲","B. 乙")));assertEquals("true",ReviewParser.canonical("judgement","正确",Collections.emptyList()));assertThrows(IOException.class,()->ReviewParser.canonical("judgement","可能正确",Collections.emptyList()));}
 @Test void dedupWrongRecordsAndPublishedAnswerSurviveRestart()throws Exception{
  Path dir=Files.createTempDirectory("review-store-");Path file=dir.resolve("library.json");ReviewStore store=new ReviewStore(file);store.course("c","课程甲");store.add("c","章节小测","第1章","source1",Collections.singletonList(official()),0);store.add("c","章节小测","第1章","source1",Collections.singletonList(official()),0);assertEquals(1,store.questions("c",false).size());
  String id=(String)store.questions("c",false).get(0).get("id");assertEquals(false,store.check("c",id,"B").get("correct"));ReviewStore loaded=new ReviewStore(file);assertEquals(1,loaded.questions("c",true).size());assertEquals(true,loaded.check("c",id,"A").get("correct"));assertEquals(1,loaded.questions("c",true).size());assertThrows(IOException.class,()->loaded.check("other-course",id,"A"));
 }
 @Test void unknownAnswersCannotBeScoredEvenWithReferenceText()throws Exception{ReviewStore store=new ReviewStore(Files.createTempDirectory("review-unknown-").resolve("library.json"));store.course("c","课程");Map<String,Object> q=ReviewParser.read(page("")).get(0);q.put("aiAnswer","A");q.put("bankAnswer","A");store.add("c","作业","作业1","s",Collections.singletonList(q),0);String id=(String)store.questions("c",false).get(0).get("id");assertThrows(IOException.class,()->store.check("c",id,"A"));assertEquals(0,store.questions("c",true).size());}
 @Test void completedQuizCanBeCollectedWithoutChangingExecutionDecoder()throws Exception{
  String html="mArg = {\"defaults\":{\"cardid\":\"x\"},\"attachments\":[{\"isPassed\":true,\"type\":\"workid\",\"jobid\":\"work-1\",\"property\":{\"title\":\"已完成小测\"}}]};";
  assertEquals(0,CourseCardDecoder.decode(html).getFirst().size());assertEquals(1,CourseCardDecoder.decode(html,true).getFirst().size());
 }
 @Test void wordModesContainSourcesAndDifferentAnswerPlacement()throws Exception{
  Map<String,Object> q=official();q.put("kind","章节小测");q.put("unit","第1章");Map<String,Object> snapshot=new LinkedHashMap<>();snapshot.put("course",Collections.singletonMap("name","课程测试"));snapshot.put("questions",Arrays.asList(q));String review=xml(ReviewDocx.create(snapshot,false)),self=xml(ReviewDocx.create(snapshot,true));assertTrue(review.contains("平台公布答案：A"));assertTrue(review.contains("本人作答：B"));assertTrue(self.indexOf("答案与来源")<self.indexOf("平台公布答案：A"));assertTrue(review.contains("考试读题尚未接入"));
 }
 static String xml(byte[] bytes)throws Exception{try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry e;while((e=zip.getNextEntry())!=null)if(e.getName().equals("word/document.xml")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=zip.read(buf))!=-1)out.write(buf,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}}throw new IOException("No document");}
}
